cpp 复制 #include "ZufyUI.h" #include "ZufyUIWidgets.h" using namespace ZufyUI ; int APIENTRY wWinMain ( HINSTANCE , HINSTANCE , LPWSTR , int ) { // Windows 子系统（/SUBSYSTEM:WINDOWS） Application app = Application :: Instance (); auto win = app . CreateWindow ( 900 , 600 , L "Hello ZufyUI" ); auto root = win -> GetRootColumnBox (); // 默认根是 ColumnBox，margin(20)，spacing 10 auto btn = std :: make_shared < Button > ( L "点我" ); btn -> Connect ( btn -> Clicked , [] { /* ... */ }); root -> AddChild ( btn ); win -> Show (); // Create 不会自动 Show（v1.8.0 起） return app . Run (); } #include "ZufyUI.h"
#include "ZufyUIWidgets.h"
using namespace ZufyUI;

int APIENTRY wWinMain(HINSTANCE, HINSTANCE, LPWSTR, int) {   // Windows 子系统（/SUBSYSTEM:WINDOWS）
    Application app = Application::Instance();
    auto win = app.CreateWindow(900, 600, L"Hello ZufyUI");
    auto root = win->GetRootColumnBox();          // 默认根是 ColumnBox，margin(20)，spacing 10
    auto btn  = std::make_shared<Button>(L"点我");
    btn->Connect(btn->Clicked, [] { /* ... */ });
    root->AddChild(btn);
    win->Show();                                  // Create 不会自动 Show（v1.8.0 起）
    return app.Run();
}  易错 GUI 程序用 wWinMain + /SUBSYSTEM:WINDOWS 。若坚持用 int main() ，请把子系统设为控制台 /SUBSYSTEM:CONSOLE ，或加 #pragma comment(linker, "/SUBSYSTEM:WINDOWS /ENTRY:mainCRTStartup") ，否则链接会找不到入口。

cpp 复制 struct Color { float r , g , b , a ; // 分量范围 [0,1]，不是 0..255 Color ( float r = 0 , float g = 0 , float b = 0 , float a = 1.0f ); static Color FromArgb ( uint8_t a , uint8_t r , uint8_t g , uint8_t b ); D2D1_COLOR_F ToD2D () const ; static Color Lerp ( const Color & c1 , const Color & c2 , float t ); }; struct Color {
    float r, g, b, a;                 // 分量范围 [0,1]，不是 0..255
    Color(float r=0, float g=0, float b=0, float a=1.0f);
    static Color FromArgb(uint8_t a, uint8_t r, uint8_t g, uint8_t b);
    D2D1_COLOR_F ToD2D() const;
    static Color Lerp(const Color& c1, const Color& c2, float t);
};  注意 Color::Lerp(a, b, t) 的 t 不做 clamp ，请自行保证在 0..1（超出会外插）。  易错 分量是浮点 [0,1] ；写 Color(255,0,0) 会得到“超亮”的错色。整数入参请用 Color::FromArgb(255,255,0,0) 。

cpp 复制 struct Rect { float x , y , width , height ; Rect ( float x = 0 , float y = 0 , float w = 0 , float h = 0 ); bool Contains ( float px , float py ) const ; // 半开区间：x<=px<x+w D2D1_RECT_F ToD2D () const ; }; struct Rect {
    float x, y, width, height;
    Rect(float x=0, float y=0, float w=0, float h=0);
    bool Contains(float px, float py) const;   // 半开区间：x<=px<x+w
    D2D1_RECT_F ToD2D() const;
};  Contains 是 左闭右开 。命中测试多处依赖它。

cpp 复制 class Connection { void disconnect (); bool isConnected () const ; explicit operator bool () const ; // 析构不自动断开 }; class Connection {
    void disconnect();
    bool isConnected() const;
    explicit operator bool() const;   // 析构不自动断开
};  默认随接收者的 ConnectionGroup 在其析构时断开； Connection 自身析构不断开 。 disconnect() 会让已排队的 UIThread / NewThread 任务逻辑失效，但 不会中断已经执行中的槽 。  易错 Connection 不是 RAII 守卫 ；临时句柄析构不会断开，必须显式 disconnect() 或依赖接收者 group。 可以忽略 connect 的返回值；信号销毁后再 disconnect 是安全的（ alive 为原子标志）。  版本 ： v1.8.1 起为被动句柄语义； v1.24.0 起存活标志原子化并取消排队任务。

cpp 复制 class ConnectionGroup : public std :: enable_shared_from_this < ConnectionGroup > { void disconnectAll (); size_t size () const ; }; class ConnectionGroup : public std::enable_shared_from_this<ConnectionGroup> {
    void disconnectAll(); size_t size() const;
};  UIElement / Window 内部用它批量断开自己注册的所有连接。 size() 只统计仍存活的连接；已手动断开的连接不计数。  易错 ConnectionGroup 的 disconnectAll() 只移除连接，不执行用户槽。

cpp 复制 template < typename ... TArgs > class ZSignal { using SlotType = std :: function < void ( TArgs ...) > ; Connection connect ( SlotType slot , ConnectionThread thread = ConnectionThread :: CurrentThread , std :: shared_ptr < ConnectionGroup > group = nullptr ); template < class Receiver , class Slot > Connection connect ( Receiver * receiver , Slot && slot , ConnectionThread thread = ConnectionThread :: CurrentThread ); void Fire ( TArgs ... targs ) const ; // 触发 void operator ()( TArgs ... targs ) const ; }; template<typename... TArgs> class ZSignal {
    using SlotType = std::function<void(TArgs...)>;
    Connection connect(SlotType slot,
                       ConnectionThread thread = ConnectionThread::CurrentThread,
                       std::shared_ptr<ConnectionGroup> group = nullptr);
    template<class Receiver, class Slot>
    Connection connect(Receiver* receiver, Slot&& slot,
                       ConnectionThread thread = ConnectionThread::CurrentThread);
    void Fire(TArgs... targs) const;    // 触发
    void operator()(TArgs... targs) const;
};  触发用 Fire （ 没有 emit 宏 ）。 ZSignal 不可拷贝、不可移动 ；信号是控件/窗口的成员，不要放进可移动容器。 信号参数按 左值 传给槽；槽不要写 T&& 形参，大对象建议 const T& 。  易错 Fire 基于 快照 遍历，槽内可以安全 disconnect ；槽内再次 Fire 同一信号会走“重入”分支（局部拷贝）， 不要 在重入里做递归深链。 Fire 与 ZSignal 析构并发是 UB；信号必须在同一线程完成触发/析构。 槽抛异常会直接穿出 Fire ，后续槽不再执行；信号槽内不建议抛异常。  版本 ： v1.18.0 加 RAII 守卫：槽抛异常也会正确还原重入深度并释放快照； v1.24.0 禁止移动。

elem->Connect(sig, slot) 、 Connect(elem, sig, slot) 、 sig.connect(elem, slot) 都把连接登记到 elem 的 ConnectionGroup ， elem 析构时自动断开； Window 同样支持。 ConnectWeak(self, sig, slot) 用弱引用；槽第一个参数为 T* 或 T& ，执行期间 self 保活；对象已销毁则不调用。 成员函数指针只走自由 Connect / ConnectWeak （有编译期类型检查）； elem->Connect(sig, &Class::Method) 不再支持。  cpp 复制 auto panel = std :: make_shared < Panel > (); panel -> Connect ( btn -> Clicked , [ this ] { Refresh (); }); Connect ( panel , btn -> Clicked , & Panel :: OnClick ); btn -> Clicked . connect ( panel , [ this ] { Refresh (); }); ConnectWeak ( panel , btn -> Clicked , []( Panel * self ) { self -> Refresh (); }); ConnectWeak ( panel , btn -> Clicked , & Panel :: OnClick ); auto panel = std::make_shared<Panel>();

panel->Connect(btn->Clicked, [this] { Refresh(); });
Connect(panel, btn->Clicked, &Panel::OnClick);
btn->Clicked.connect(panel, [this] { Refresh(); });

ConnectWeak(panel, btn->Clicked, [](Panel* self) { self->Refresh(); });
ConnectWeak(panel, btn->Clicked, &Panel::OnClick);  注意 Menu / MenuItem / Timer 仍用 signal.connect ， 不自动断开 。  易错 ConnectWeak 的槽里不要再按值捕获 self 的 shared_ptr ，否则会形成“信号→槽→self→信号”的强引用环。

cpp 复制 namespace UIZSignals { inline ZSignal < Window * , ID2D1RenderTarget *> DrawOverlay ; inline ZSignal < Window * , float , float > GlobalMouseDown ; inline ZSignal < Window *> WindowActivated , WindowDeactivated ; inline ZSignal < Window * , UIElement *> ElementCaptureRequest , ElementCaptureRelease , RepaintRequest ; inline ZSignal < Window *> LayoutInvalidated ; inline ZSignal <> DeviceReset , ReloadAcrylic ; inline ZSignal < const std :: wstring &> Error ; // v1.16.0 } namespace UIZSignals {
    inline ZSignal<Window*, ID2D1RenderTarget*> DrawOverlay;
    inline ZSignal<Window*, float, float> GlobalMouseDown;
    inline ZSignal<Window*> WindowActivated, WindowDeactivated;
    inline ZSignal<Window*, UIElement*> ElementCaptureRequest, ElementCaptureRelease, RepaintRequest;
    inline ZSignal<Window*> LayoutInvalidated;
    inline ZSignal<> DeviceReset, ReloadAcrylic;
    inline ZSignal<const std::wstring&> Error;         // v1.16.0
}  RepaintRequest / LayoutInvalidated /capture 信号只对 未挂载 元素兜底；已挂载元素直接走 Window 。 DeviceReset ：释放一切与渲染目标/设备绑定的缓存（如 ImageDeviceCache ）。  易错 DrawOverlay 带 Window* ，subscriber 必须 按 GetWindow() 过滤，否则窗口 A 的浮层会画到窗口 B 上（经典多窗口串扰）。  版本 ： UIZSignals::Error = v1.16.0 。

cpp 复制 struct FontSpec { std :: wstring familyName = L "Segoe UI" ; float size = 14.0f ; DWRITE_FONT_WEIGHT weight = DWRITE_FONT_WEIGHT_NORMAL ; DWRITE_FONT_STYLE style = DWRITE_FONT_STYLE_NORMAL ; DWRITE_FONT_STRETCH stretch = DWRITE_FONT_STRETCH_NORMAL ; std :: wstring locale = L "en-us" ; bool operator ==/!= (...) const ; }; struct FontSpec {
    std::wstring familyName = L"Segoe UI";
    float size = 14.0f;
    DWRITE_FONT_WEIGHT weight = DWRITE_FONT_WEIGHT_NORMAL;
    DWRITE_FONT_STYLE  style  = DWRITE_FONT_STYLE_NORMAL;
    DWRITE_FONT_STRETCH stretch = DWRITE_FONT_STRETCH_NORMAL;
    std::wstring locale = L"en-us";
    bool operator==/!=(...) const;
};

