IDWriteFactory* GetFactory();
IDWriteTextFormat* GetFormat(const FontSpec&);        // 格式缓存，永不淘汰
ComPtr<IDWriteTextLayout> GetRawLayout(text, fmt, maxW, maxH, noWrap);
ComPtr<IDWriteTextLayout> GetDisplayLayout(origText, fmt, maxW, maxH, noWrap);   // 带省略号
ComPtr<IDWriteTextLayout> GetStyledLayout(text, fmt, w, h, noWrap, hAlign, vAlign, lineSpacing, maxLines);
ComPtr<IDWriteTextLayout> GetStyledDisplayLayout(...);
void CacheDisplayLayout(...); void CacheStyledDisplayLayout(...);
void SetGlobalFont(const FontSpec&);
ZSignal<> GlobalFontChanged;  布局缓存 有上限 （400 条，FIFO 淘汰 ¼）；返回强引用（ ComPtr ），调用期间不会被淘汰。  易错 返回的 layout 是 共享只读 对象， 不要 对它 SetTextAlignment/SetLineSpacing/SetTrimming ——缓存 key 会与对象不一致。 GetFormat 返回的 IDWriteTextFormat* 永不淘汰 ，请勿修改它。 GetFormat 的共享 format 把 ParagraphAlignment 设成了 CENTER 。 不要直接拿它画多行自绘文本 ，否则会被垂直居中到高盒外（看起来“没字”）；用 GetStyledLayout(..., vAlign) 或自建 format 并设 NEAR 。  版本 ： GetStyledLayout 与全局布局缓存在 v1.10.1 强化；有界缓存/强引用契约在 v1.15.0 前后定型。

cpp 复制 enum class Icon : unsigned short { None = 0x0000 , Add = 0xE710 , Remove = 0xE738 , ..., Pin = 0xE718 , View = 0xE890 , ... }; inline const std :: wstring & IconFontFamily (); // Segoe Fluent Icons → 回退 Segoe MDL2 Assets inline std :: wstring IconGlyph ( Icon ); // 码点 → 单字宽字符串 enum class Icon : unsigned short { None=0x0000, Add=0xE710, Remove=0xE738, ..., Pin=0xE718, View=0xE890, ... };
inline const std::wstring& IconFontFamily();   // Segoe Fluent Icons → 回退 Segoe MDL2 Assets
inline std::wstring IconGlyph(Icon);           // 码点 → 单字宽字符串  易错 枚举值 就是字体码点 （无独立映射表）。字体回退 只在首次静态探测 ，运行期换系统字体不会重探；个别 Win11 专有字形在两版字体里缺失会显示方框。  版本 ： v1.13.0 起 Icon 下沉到 ZufyUIWidgets.h ，所有 Label 派生控件获得 SetIcon 。

