virtual float GetDefaultHorizontalStretchWeight() const;   // 同理 Vertical  拉伸权值 ：容器（ ColumnBox / RowBox / GridLayout ）把 剩余空间 按子元素权值分配。 FillWidth/Height 等价“该轴权值 1”。 GetDefault* 是类型默认， Set* 覆盖它。  易错 SetWidth/SetHeight 是 固定尺寸 ； SetFillWidth/Height 是 填满父轴 ；两者与拉伸权值叠加，行为要分清。 GetDesiredSize() 是上一次 Measure 的结果；未测量过/刚改内容时可能是旧值。  版本 ： SetStretchWeights / GetDefault* 自初版存在； ColumnBox / RowBox / GridLayout 真正按显式权值分配剩余空间 = v1.17.0 。

cpp 复制 virtual void Draw ( ID2D1RenderTarget * rt ) = 0 ; virtual void RefreshChildren (); // 更新阶段（UI 线程）重建可见子列表 virtual const std :: vector < UIElement *>& GetChildren () const ; // 渲染阶段纯读 virtual bool UseCache () const ; void SetUseCache ( bool ); // 默认 true virtual std :: optional < D2D1_RECT_F > GetClipRect () const ; void SetClipRect ( const std :: optional < Rect >& ); void SetBleed ( float ); // 阴影/外发光留边 virtual void ReleaseDeviceResources (); // 只释放自身 void ReleaseDeviceResourcesRecursive (); // 释放整棵子树 virtual D2D1 :: Matrix3x2F GetChildRenderTransform ( UIElement * child ) const ; virtual void Draw(ID2D1RenderTarget* rt) = 0;
virtual void RefreshChildren();                       // 更新阶段（UI 线程）重建可见子列表
virtual const std::vector<UIElement*>& GetChildren() const;   // 渲染阶段纯读
virtual bool UseCache() const;   void SetUseCache(bool);      // 默认 true
virtual std::optional<D2D1_RECT_F> GetClipRect() const;
void SetClipRect(const std::optional<Rect>&);
void SetBleed(float);            // 阴影/外发光留边
virtual void ReleaseDeviceResources();        // 只释放自身
void ReleaseDeviceResourcesRecursive();        // 释放整棵子树
virtual D2D1::Matrix3x2F GetChildRenderTransform(UIElement* child) const;  缓存机制 ： UseCache()==true 的元素渲染到自身 ID2D1Bitmap1 离屏位图；仅当被 RequestRepaint() 标记或尺寸变化时重建。出现阴影时自动加 bleed 。  易错 每帧内容在变 （动画、实时文本、旋转）或 实例极多 （上千个）的控件应 SetUseCache(false) ，否则显存与重建开销爆炸。 GetChildren() 在渲染阶段 必须纯读 ；渲染前要保证 RefreshChildren() 已调用（窗口在 AdvanceFrame 里统一做）。 ReleaseDeviceResources() 只释放自身；释放整棵子树用 ReleaseDeviceResourcesRecursive() 。  版本 ： ReleaseDeviceResourcesRecursive() = v1.18.0 （用于隐藏页缓存延迟释放）； SetUseCache(false) 现在会 立即释放 已有位图。

