using namespace ZufyUI;
using namespace ZufyUI::dsl;

int APIENTRY wWinMain(HINSTANCE, HINSTANCE, LPWSTR, int) {
    auto nameBox = ZTxt().placeholder(L"在这里输入...");
    auto greeting = ZLbl(L"你好，等待输入...");
    auto greetBtn = ZBtn(L"打招呼");

    auto root = ZCol(
        ZRow(ZLbl(L"你的名字："), nameBox).spacing(12),
        greeting.vWeight(1),
        ZRow(greetBtn).spacing(12)
    ).spacing(10).margin(Thickness(20));

    greetBtn.on<&Button::Clicked>([nameBox, greeting] {
        auto name = nameBox->GetText();
        greeting->SetText(name.empty() ? L"你好，陌生人。" : L"你好，" + name + L"！");
    });

    return ZApp().title(L"ZufyUI DSL 示例").size(760, 520).root(root).run();
}  ZTxt() / ZLbl() / ZBtn() 返回 已经创建好的控件句柄 ； nameBox 不是空壳。 不需要先写 Ref<TextBox>() 再“等它变成控件”。 ZApp().run() 内部已经 Create → 应用配置 → Show → Run ，不要额外 win->Show() 。 如果项目启用了预编译头，文件第一行需要 #include "pch.h" ；这是工程配置，不属于 ZufyUI API。  推荐写法 能内联就内联： ZRow(ZLbl(L"名字"), ZTxt().placeholder(L"...")) 。只有后面还要读取/修改某个控件时，才用 auto nameBox = ZTxt() 保存句柄；不要用空 Ref<T>() 占位。

auto nameBox = ZTxt(); 返回 Ref<TextBox> ，内部持有真实的 std::shared_ptr<TextBox> ； auto 把类型藏起来，正常使用不需要写出 Ref 。 Ref<T>() 是 空句柄 ，不是工厂：它不会创建控件， ZRow / ZCol 会忽略它，直接 -> 访问会得到空指针。普通界面不需要用它。 只有“类成员先声明、之后再赋值”或“明确需要可空引用”才用默认空 Ref ；即使是这种场景，也建议优先用 std::shared_ptr<T> + 成员初始化。 不想用 Ref 的链式糖时，DSL 容器也直接接受 shared_ptr ，事件改回核心 Connect 即可：  cpp 复制 auto nameBox = std :: make_shared < TextBox > (); nameBox -> SetPlaceholder ( L "在这里输入..." ); auto root = ZCol ( ZRow ( ZLbl ( L "你的名字：" ), nameBox ). spacing ( 12 ) ); nameBox -> Connect ( nameBox -> TextChanged , []( const std :: wstring & ) {}); auto nameBox = std::make_shared<TextBox>();
nameBox->SetPlaceholder(L"在这里输入...");

auto root = ZCol(
    ZRow(ZLbl(L"你的名字："), nameBox).spacing(12)
);

nameBox->Connect(nameBox->TextChanged, [](const std::wstring&) {});  类成员示例（不推荐把空 Ref 当普通构造）：  cpp 复制 dsl :: Ref < Label > status_ ; // 空句柄，等待赋值 status_ = dsl :: ZLbl ( L "就绪" ); // 赋值后才指向真实控件 dsl::Ref<Label> status_;          // 空句柄，等待赋值
status_ = dsl::ZLbl(L"就绪");     // 赋值后才指向真实控件

直接链到 .run() ：  cpp 复制 return ZApp () . title ( L "ZufyUI DSL 示例" ) . size ( 760 , 520 ) . root ( ZCol ( ZLbl ( L "你好" ))) . run (); return ZApp()
    .title(L"ZufyUI DSL 示例")
    .size(760, 520)
    .root(ZCol(ZLbl(L"你好")))
    .run();  需要保存 builder 时，先构造再分步调用：  cpp 复制 WindowApp app = ZApp (); app . title ( L "ZufyUI DSL 示例" ); app . size ( 760 , 520 ); app . root ( ZCol ( ZLbl ( L "你好" ))); return app . run (); WindowApp app = ZApp();
app.title(L"ZufyUI DSL 示例");
app.size(760, 520);
app.root(ZCol(ZLbl(L"你好")));
return app.run();  不要写 auto app = ZApp().title(...) ：链式方法返回 WindowApp& ，而 WindowApp 拷贝构造被删除，所以这条会编译失败。 WindowApp 可移动但不可拷贝；直接链到 .run() ，或先 WindowApp app = ZApp(); 是正确写法。

